"use strict";(self.webpackChunkwoocommerce_marketplace_shopify_connector_doc=self.webpackChunkwoocommerce_marketplace_shopify_connector_doc||[]).push([[470],{6019(e,o,n){n.r(o),n.d(o,{_pageData:()=>a,default:()=>s});var t=n(641);const a=JSON.parse('{"path":"/","title":"WooCommerce Marketplace Shopify Connector Documentation","lang":"en-US","frontmatter":{"home":true,"title":"WooCommerce Marketplace Shopify Connector Documentation","description":"Seller documentation for WooCommerce Marketplace Shopify Connector — connect a Shopify store to a WooCommerce marketplace seller account, map collections to categories, import and export products and orders, apply price rules, and keep both catalogues in sync in real time.","heroImage":"/images/shopify-connector/hero-connector.svg","heroImageDark":"/images/shopify-connector/hero-connector-dark.svg","heroAlt":"A WooCommerce marketplace and a Shopify store joined by a two-way sync hub","heroHeight":220,"heroText":"WooCommerce Marketplace Shopify Connector Documentation","tagline":"Let every seller in your WooCommerce marketplace run their Shopify store and their marketplace shop as one catalogue — products, collections, orders, stock and prices moving in both directions, from a single screen inside My Account.","actions":[{"text":"Get Started →","link":"/shopify-connector/overview","type":"primary"},{"text":"Buy Now","link":"https://store.webkul.com/woocommerce-marketplace-shopify-connector.html","type":"secondary"},{"text":"Demo","link":"https://wordpressdemo.webkul.com/woocommerce-marketplace-shopify-connector/","type":"secondary"}],"footer":"© 2010-2026 Webkul. All Rights Reserved."},"git":{},"filePathRelative":"README.md"}'),r={name:"README.md"},s=(0,n(6262).A)(r,[["render",function(e,o,n,a,r,s){return(0,t.uX)(),(0,t.CE)("div",null,[...o[0]||(o[0]=[(0,t.Fv)('<h2 id="why-marketplace-shopify-connector" tabindex="-1"><a class="header-anchor" href="#why-marketplace-shopify-connector"><span>Why Marketplace Shopify Connector?</span></a></h2><p>A seller who already trades on Shopify and joins your marketplace normally has to maintain two catalogues by hand — enter every product twice, keep the prices matched, and copy each order across so stock stays honest. The <strong>WooCommerce Marketplace Shopify Connector</strong> removes that duplication. The seller connects their store once, decides which way each kind of data should flow, and the connector keeps both sides current.</p><div class="qb-cards"><a class="qb-card" href="/woocommerce-marketplace-shopify-connector/shopify-connector/setup-wizard.html"><span class="qb-card__icon"><svg viewBox="0 0 24 24" fill="none" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"></circle><polygon points="16.24 7.76 14.12 14.12 7.76 16.24 9.88 9.88 16.24 7.76"></polygon></svg></span><h3 class="qb-card__title">Guided Setup Wizard</h3><p class="qb-card__desc">Go from a fresh install to a verified Shopify connection in four guided steps — welcome, store details, credentials, and a confirmation summary.</p><span class="qb-card__more">Learn more <svg viewBox="0 0 24 24" fill="none" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><line x1="5" y1="12" x2="19" y2="12"></line><polyline points="12 5 19 12 12 19"></polyline></svg></span></a><a class="qb-card" href="/woocommerce-marketplace-shopify-connector/shopify-connector/connecting-your-store.html"><span class="qb-card__icon"><svg viewBox="0 0 24 24" fill="none" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 9l1.5-5h15L21 9"></path><path d="M4 9v10a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V9"></path><path d="M9 21v-6h6v6"></path></svg></span><h3 class="qb-card__title">Multiple Shopify Accounts</h3><p class="qb-card__desc">A seller can connect more than one Shopify store, switch between them from the header, and give each its own settings, mappings and price rules.</p><span class="qb-card__more">Learn more <svg viewBox="0 0 24 24" fill="none" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><line x1="5" y1="12" x2="19" y2="12"></line><polyline points="12 5 19 12 12 19"></polyline></svg></span></a><a class="qb-card" href="/woocommerce-marketplace-shopify-connector/shopify-connector/importing-products.html"><span class="qb-card__icon"><svg viewBox="0 0 24 24" fill="none" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"></path><polyline points="7 10 12 15 17 10"></polyline><line x1="12" y1="15" x2="12" y2="3"></line></svg></span><h3 class="qb-card__title">Import Products</h3><p class="qb-card__desc">Pull simple and variable products with images, price, SKU, stock, weight and every option, then create them in WooCommerce with the status you choose.</p><span class="qb-card__more">Learn more <svg viewBox="0 0 24 24" fill="none" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><line x1="5" y1="12" x2="19" y2="12"></line><polyline points="12 5 19 12 12 19"></polyline></svg></span></a><a class="qb-card" href="/woocommerce-marketplace-shopify-connector/shopify-connector/exporting-products.html"><span class="qb-card__icon"><svg viewBox="0 0 24 24" fill="none" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"></path><polyline points="17 8 12 3 7 8"></polyline><line x1="12" y1="3" x2="12" y2="15"></line></svg></span><h3 class="qb-card__title">Export Products</h3><p class="qb-card__desc">Push the seller’s own products into the Shopify catalogue — all at once, a selection, or one row at a time — and update them without creating duplicates.</p><span class="qb-card__more">Learn more <svg viewBox="0 0 24 24" fill="none" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><line x1="5" y1="12" x2="19" y2="12"></line><polyline points="12 5 19 12 12 19"></polyline></svg></span></a><a class="qb-card" href="/woocommerce-marketplace-shopify-connector/shopify-connector/importing-orders.html"><span class="qb-card__icon"><svg viewBox="0 0 24 24" fill="none" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="9" cy="21" r="1"></circle><circle cx="20" cy="21" r="1"></circle><path d="M1 1h4l2.68 13.39a2 2 0 0 0 2 1.61h9.72a2 2 0 0 0 2-1.61L23 6H6"></path></svg></span><h3 class="qb-card__title">Import &amp; Export Orders</h3><p class="qb-card__desc">Bring Shopify orders into WooCommerce with the status you pick, and create marketplace orders on Shopify by hand or automatically at checkout.</p><span class="qb-card__more">Learn more <svg viewBox="0 0 24 24" fill="none" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><line x1="5" y1="12" x2="19" y2="12"></line><polyline points="12 5 19 12 12 19"></polyline></svg></span></a><a class="qb-card" href="/woocommerce-marketplace-shopify-connector/shopify-connector/category-mapping.html"><span class="qb-card__icon"><svg viewBox="0 0 24 24" fill="none" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M22 19a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h5l2 3h9a2 2 0 0 1 2 2z"></path></svg></span><h3 class="qb-card__title">Category Mapping</h3><p class="qb-card__desc">Fetch the Shopify collections, pair each one with a WooCommerce category, and choose whether imports cover the whole store or only the mapped collections.</p><span class="qb-card__more">Learn more <svg viewBox="0 0 24 24" fill="none" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><line x1="5" y1="12" x2="19" y2="12"></line><polyline points="12 5 19 12 12 19"></polyline></svg></span></a><a class="qb-card" href="/woocommerce-marketplace-shopify-connector/shopify-connector/price-rules.html"><span class="qb-card__icon"><svg viewBox="0 0 24 24" fill="none" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M20.59 13.41l-7.17 7.17a2 2 0 0 1-2.83 0L2 12V2h10l8.59 8.59a2 2 0 0 1 0 2.82z"></path><line x1="7" y1="7" x2="7.01" y2="7"></line></svg></span><h3 class="qb-card__title">Price Rules</h3><p class="qb-card__desc">Add or subtract a fixed amount or a percentage inside a price band, in whichever direction you sync, without touching the source catalogue.</p><span class="qb-card__more">Learn more <svg viewBox="0 0 24 24" fill="none" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><line x1="5" y1="12" x2="19" y2="12"></line><polyline points="12 5 19 12 12 19"></polyline></svg></span></a><a class="qb-card" href="/woocommerce-marketplace-shopify-connector/shopify-connector/webhooks-and-auto-sync.html"><span class="qb-card__icon"><svg viewBox="0 0 24 24" fill="none" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="23 4 23 10 17 10"></polyline><path d="M20.49 15a9 9 0 1 1-2.12-9.36L23 10"></path></svg></span><h3 class="qb-card__title">Live Webhook Sync</h3><p class="qb-card__desc">Product updates, deletions and order fulfilments arrive as signed Shopify webhooks and are applied to WooCommerce by a background queue.</p><span class="qb-card__more">Learn more <svg viewBox="0 0 24 24" fill="none" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><line x1="5" y1="12" x2="19" y2="12"></line><polyline points="12 5 19 12 12 19"></polyline></svg></span></a><a class="qb-card" href="/woocommerce-marketplace-shopify-connector/shopify-connector/product-data-mapping.html"><span class="qb-card__icon"><svg viewBox="0 0 24 24" fill="none" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"></path><polyline points="14 2 14 8 20 8"></polyline><line x1="16" y1="13" x2="8" y2="13"></line><line x1="16" y1="17" x2="8" y2="17"></line></svg></span><h3 class="qb-card__title">Field-by-Field Reference</h3><p class="qb-card__desc">Exactly which product and order fields travel in each direction, how product type and stock are decided, and which fields an update may write.</p><span class="qb-card__more">Learn more <svg viewBox="0 0 24 24" fill="none" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><line x1="5" y1="12" x2="19" y2="12"></line><polyline points="12 5 19 12 12 19"></polyline></svg></span></a></div><h2 id="how-it-works" tabindex="-1"><a class="header-anchor" href="#how-it-works"><span>How it works</span></a></h2><div class="qb-steps"><a class="qb-step" href="/woocommerce-marketplace-shopify-connector/shopify-connector/shopify-app-setup.html"><strong>Create the Shopify app</strong><span>Create an app in the Shopify Developer Dashboard for the Client ID and Secret, or use an existing legacy custom app’s access token.</span></a><a class="qb-step" href="/woocommerce-marketplace-shopify-connector/shopify-connector/setup-wizard.html"><strong>Connect the store</strong><span>The seller runs the four-step wizard from My Account. It verifies the credentials against Shopify and registers the webhooks before it finishes.</span></a><a class="qb-step" href="/woocommerce-marketplace-shopify-connector/shopify-connector/importing-products.html"><strong>Map, import, export</strong><span>Pair collections with categories, pull the Shopify catalogue in, push marketplace products out, and let orders flow both ways.</span></a></div><h2 id="what-s-new-in-v2-0-0" tabindex="-1"><a class="header-anchor" href="#what-s-new-in-v2-0-0"><span>What&#39;s New in v2.0.0</span></a></h2><ul class="qb-whats-new-list"><li class="qb-whats-new-item"><span class="qb-whats-new-item__icon"><svg viewBox="0 0 24 24" fill="none" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="3" width="18" height="18" rx="2"></rect><path d="M3 9h18M9 9v12"></path></svg></span><div class="qb-whats-new-item__content"><strong>Shopify Developer Dashboard apps</strong> — Connect through an OAuth app created in the Developer Dashboard, with copy-ready redirect URIs and a one-click <em>Refresh the app details</em> action after publishing a new app version. <a href="/woocommerce-marketplace-shopify-connector/shopify-connector/shopify-app-setup.html">Creating the Shopify App →</a></div></li><li class="qb-whats-new-item"><span class="qb-whats-new-item__icon"><svg viewBox="0 0 24 24" fill="none" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="8" cy="15" r="4"></circle><path d="M11 12L21 2M16 7l3 3"></path></svg></span><div class="qb-whats-new-item__content"><strong>Legacy custom apps still supported</strong> — Stores that already use an Admin API access token keep working. Shopify stopped issuing new legacy custom apps on 1 January 2026, so new connections should use the Developer Dashboard. <a href="/woocommerce-marketplace-shopify-connector/shopify-connector/connecting-your-store.html">Connecting Your Store →</a></div></li><li class="qb-whats-new-item"><span class="qb-whats-new-item__icon"><svg viewBox="0 0 24 24" fill="none" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M13 2L3 14h8l-1 8 10-12h-8l1-8z"></path></svg></span><div class="qb-whats-new-item__content"><strong>GraphQL Admin API throughout</strong> — Every catalogue, order and webhook call goes through Shopify’s GraphQL Admin API, with the three sync webhooks registered automatically when a store is connected. <a href="/woocommerce-marketplace-shopify-connector/shopify-connector/webhooks-and-auto-sync.html">Webhooks &amp; Auto-Sync →</a></div></li><li class="qb-whats-new-item"><span class="qb-whats-new-item__icon"><svg viewBox="0 0 24 24" fill="none" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 2l8 3v6c0 5-3.5 9-8 11-4.5-2-8-6-8-11V5l8-3z"></path><path d="M8.5 12l2.5 2.5 4.5-4.5"></path></svg></span><div class="qb-whats-new-item__content"><strong>WordPress 7.0 &amp; WooCommerce 10.7 compatible</strong> — Tested against the modern WooCommerce stack, with High-Performance Order Storage and cart/checkout blocks compatibility declared. <a href="/woocommerce-marketplace-shopify-connector/shopify-connector/installation.html">Installation →</a></div></li></ul><div class="qb-cta"><h3>Ready to let your sellers run one catalogue instead of two?</h3><p>Connect a Shopify store once, then move products, collections, orders, stock and prices in both directions — without entering anything twice.</p><div class="qb-cta__actions"><a class="qb-cta__btn qb-cta__btn--solid" href="https://store.webkul.com/woocommerce-marketplace-shopify-connector.html">Buy Now</a><a class="qb-cta__btn qb-cta__btn--ghost" href="https://webkul.com/ticket/">Get Support</a></div></div><h2 id="helpful-links" tabindex="-1"><a class="header-anchor" href="#helpful-links"><span>Helpful Links</span></a></h2><ul><li><a href="https://wordpressdemo.webkul.com/woocommerce-marketplace-shopify-connector/" target="_blank" rel="noopener noreferrer">Live demo — try the connector</a></li><li><a href="https://store.webkul.com/woocommerce-marketplace-shopify-connector.html" target="_blank" rel="noopener noreferrer">Marketplace Shopify Connector product page</a></li><li><a href="https://codecanyon.net/item/woocommerce-multi-vendor-shopify-connector/39729460" target="_blank" rel="noopener noreferrer">Marketplace Shopify Connector on CodeCanyon</a></li><li><a href="https://dev.shopify.com/" target="_blank" rel="noopener noreferrer">Shopify Developer Dashboard</a></li><li><a href="https://webkul.com/ticket/" target="_blank" rel="noopener noreferrer">Webkul support desk</a></li></ul>',10)])])}]])}}]);